// cromo.js - the official "cromo" (collectible card) of The Bazaar, as HTML strings.
//
// Port of the card component from the official SPA (bazaar.causaprima.ai, chunk
// Cromo-*.js + Cromo-*.css). The card is drawn entirely in SVG: a sky gradient in the
// set colour, a sun, one of 39 Madrid scenes picked from the card name, the title in
// a condensed display face, and a dark bar with "LAV 07 · #07/30", a rarity pip and the
// rarity label. Rare+ cards get a holo wash and a light streak, epic/legendary get
// sparkles plus an animated foil edge (CSS, see cromo.css).
//
//   import { cromo, cromoTilt } from "./cromo.js";
//   el.innerHTML = cromo(card, { set, copies, size: "md" });
//
// No dependencies. Every string that comes from the API is HTML-escaped.

const ESC = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ESC[c]);

// ---- small helpers ported from the official bundle (useEvents/index chunks) ----

const RARITIES = ["common", "uncommon", "rare", "epic", "legendary"];
const RARITY_COLOR = { common: "#9AA4B8", uncommon: "#3DDC97", rare: "#4C8DFF", epic: "#B061FF", legendary: "#FFC44D" };
const RARITY_LABEL = { common: "Common", uncommon: "Uncommon", rare: "Rare", epic: "Epic", legendary: "Legendary" };
const isNum = (v) => typeof v === "number" && Number.isFinite(v);

function rgb(hex) {
  let t = String(hex || "").replace("#", "").trim();
  if (t.length === 3) t = t.split("").map((c) => c + c).join("");
  const n = Number.parseInt(t.slice(0, 6), 16);
  return Number.isNaN(n) ? [136, 136, 136] : [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
const toHex = (r, g, b) => "#" + [r, g, b].map((v) => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, "0")).join("");
/** Linear mix of two hex colours, t in [0,1]. */
function mix(a, b, t) {
  const [r, g, bl] = rgb(a), [r2, g2, b2] = rgb(b);
  return toHex(r + (r2 - r) * t, g + (g2 - g) * t, bl + (b2 - bl) * t);
}
/** FNV-1a 32-bit hash. */
function hash(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
/** Seeded PRNG (mulberry32). */
function rng(seed) {
  let t = seed >>> 0;
  return () => {
    t = (t + 1831565813) >>> 0;
    let e = t;
    e = Math.imul(e ^ (e >>> 15), e | 1);
    e ^= e + Math.imul(e ^ (e >>> 7), e | 61);
    return ((e ^ (e >>> 14)) >>> 0) / 4294967296;
  };
}
function parseId(id) {
  const m = /^([A-Z]{3})-(\d+)$/.exec(String(id || ""));
  return m ? { set: m[1], number: Number(m[2]) } : { set: String(id || "").slice(0, 3), number: 0 };
}
/** "#07/30" exactly like the official serial formatter. */
export function cromoSerial(serial, printRun) {
  if (!isNum(serial)) return "";
  if (!isNum(printRun)) return `#${serial}`;
  return `#${String(serial).padStart(Math.max(2, String(printRun).length), "0")}/${printRun}`;
}
function money(v, symbol = "P") {
  if (!isNum(v)) return "—";
  const d = Math.abs(v) < 100 && v % 1 ? 1 : 0;
  const s = Math.abs(v).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
  return `${v < 0 ? "−" : ""}${symbol}${s}`;
}

// ---- a tiny JSX-to-string shim so the official scene art can run unchanged ----

const FRAG = Symbol("fragment");
