/* eslint-enable */

// ---- card face (port of the official <CromoArt>) ----

const W = 240, HT = 336, PAD = 18, FLAV = 30;
const DISPLAY = "var(--cromo-display)";
const MONO = "var(--cromo-mono)";
const INK = "#1B0C22", CREAM = "#FFF1DA", SUN = "#FFD66B";
// sm/md/lg are the official layouts; xs is ours (no title, just a big number).
const LAYOUT = {
  xs: { bar: 92, title: 0, maxLines: 1, mono: 62, label: 0, tracking: 0 },
  sm: { bar: 40, title: 38, maxLines: 2, mono: 15, label: 0, tracking: 0.6 },
  md: { bar: 36, title: 33, maxLines: 3, mono: 11.5, label: 14.5, tracking: 0.8 },
  lg: { bar: 36, title: 33, maxLines: 3, mono: 10.5, label: 14, tracking: 1 },
};
const barTop = (size, flav) => HT - LAYOUT[size].bar - (flav ? FLAV : 0);
const barFrac = (size, flav) => 1 - barTop(size, flav) / HT;
const sparkle = (x, y, n) =>
  `M${x} ${y - n} L${x + n * 0.28} ${y - n * 0.28} L${x + n} ${y} L${x + n * 0.28} ${y + n * 0.28} L${x} ${y + n} L${x - n * 0.28} ${y + n * 0.28} L${x - n} ${y} L${x - n * 0.28} ${y - n * 0.28} Z`;

let UID = 0;
// Pin each title line to the width the official metrics expect, so a fallback font
// (when Big Shoulders Display is not installed) cannot overflow the card.
const fit = (line, size) => ` textLength="${n(S.pe(line) * size + 0.5 * Math.max(0, [...line].length - 1))}" lengthAdjust="spacingAndGlyphs"`;
const n = (v) => +(+v).toFixed(2);

function art(p) {
  const uid = `cr${(++UID).toString(36)}`;
  const id = (k) => `${k}-${uid}`;
  const seed = p.seed, name = p.name;
  const pick = S.ft(seed, name, p.scene);

  if (p.variant === "ghost") {
    return `<svg class="cromo__ghost" viewBox="0 0 200 160" preserveAspectRatio="xMidYMax meet" aria-hidden="true">${str(S._t(pick, seed, name, S.be(p.setColor), id))}</svg>`;
  }

  const size = p.size;
  const silhouette = !!p.silhouette;
  const pal = S.ye(p.setColor);
  const scenePal = silhouette ? S.be(mix(p.setColor, INK, 0.72)) : pal;
  const v = LAYOUT[size];
  const y = barTop(size, p.flavour);
  const title = v.title ? S.ge(p.title ?? name, 204, v.title, v.maxLines, 0.5) : { lines: [], size: 0 };
  const sunY = 80 + 16 * Math.max(1, title.lines.length);
  const rarity = p.rarity;
  const holo = !silhouette && (rarity === "rare" || rarity === "epic" || rarity === "legendary");
  const leg = rarity === "legendary";
  const stars = silhouette ? [] : rarity === "epic" ? [[0.18, 0.2, 5], [0.82, 0.16, 7], [0.7, 0.62, 4]] : leg ? [[0.16, 0.18, 6], [0.86, 0.28, 8], [0.3, 0.7, 4], [0.78, 0.78, 5]] : [];
  const detailed = size === "md" || size === "lg";

  const skyTop = silhouette ? mix(pal.skyTop, "#8A8494", 0.6) : pal.skyTop;
  const skyBot = silhouette ? mix(pal.skyBottom, INK, 0.4) : pal.skyBottom;

  let defs = `<linearGradient id="${id("sky")}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${skyTop}"/><stop offset="1" stop-color="${skyBot}"/></linearGradient>`;
  if (detailed) {
    defs += `<pattern id="${id("dots")}" width="6" height="6" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r="1.25" fill="${pal.dark}"/></pattern>`
      + `<linearGradient id="${id("fade")}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#fff"/></linearGradient>`
      + `<mask id="${id("halftone")}"><rect y="150" width="${W}" height="186" fill="url(#${id("fade")})"/></mask>`;
  }
  if (holo) {
    const stops = leg
      ? [[0, "#fff4c2"], [0.5, "#f3c64f"], [1, "#fff4c2"]]
      : [[0, "#ff6f91"], [0.22, "#ffc75f"], [0.4, "#f9f871"], [0.56, "#6ef3a5"], [0.72, "#4ec9ff"], [0.88, "#b58cff"], [1, "#ff6f91"]];
    defs += `<linearGradient id="${id("holo")}" x1="0" y1="0" x2="1" y2="1">${stops.map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`).join("")}</linearGradient>`
      + `<linearGradient id="${id("streak")}" x1="0" y1="0" x2="1" y2="1"><stop offset=".34" stop-color="#fff" stop-opacity="0"/><stop offset=".47" stop-color="#fff" stop-opacity=".3"/><stop offset=".6" stop-color="#fff" stop-opacity="0"/></linearGradient>`;
  }

  let body = `<rect width="${W}" height="${HT}" fill="url(#${id("sky")})"/>`;
  if (!silhouette) body += `<circle cx="176" cy="${sunY}" r="44" fill="${pal.accent}" opacity=".95"/>`;
  body += `<g transform="translate(0 ${y - 192}) scale(1.2)">${str(S._t(pick, seed, name, scenePal, id))}</g>`;
  if (detailed) body += `<rect width="${W}" height="${HT}" fill="url(#${id("dots")})" mask="url(#${id("halftone")})" opacity=".22"/>`;
  if (rarity === "uncommon" && !silhouette) body += `<rect x="3" y="3" width="234" height="${y - 6}" rx="10" fill="none" stroke="${esc(p.setColor)}" stroke-width="2"/>`;
  if (holo) {
    body += `<rect width="${W}" height="${y}" fill="url(#${id("holo")})" opacity="${leg ? 0.5 : 0.34}" style="mix-blend-mode:${leg ? "soft-light" : "overlay"}"/>`
      + `<rect width="${W}" height="${y}" fill="url(#${id("streak")})" style="mix-blend-mode:screen"/>`;
  }
  if (stars.length) body += `<path d="${stars.map(([a, b, r]) => sparkle(a * W, b * y, r)).join(" ")}" fill="${leg ? "#fff6cc" : "#ffffff"}" opacity=".92"/>`;

  if (title.lines.length) {
    const ts = title.size, dx = ts * 0.045, dy = ts * 0.06;
    const ly = (i) => PAD + ts * 0.727 + i * ts * 0.909;
    body += `<g font-weight="900" font-size="${n(ts)}" letter-spacing=".5" style="font-family:${DISPLAY}">`
      + title.lines.map((l, i) => `<text x="${n(PAD + dx)}" y="${n(ly(i) + dy)}" fill="${pal.main}" opacity=".85"${fit(l, ts)}>${esc(l)}</text>`).join("")
      + title.lines.map((l, i) => `<text x="${PAD}" y="${n(ly(i))}" fill="${pal.light}"${fit(l, ts)}>${esc(l)}</text>`).join("")
      + `</g>`;
  }

  // bottom bar
  body += `<rect y="${y}" width="${W}" height="${HT - y}" fill="${pal.dark}"/>`;
  const dotColor = p.rarityColor;
  if (size === "xs") {
    const cy = HT - v.bar / 2;
    body += `<text x="${PAD}" y="${n(cy + v.mono * 0.36)}" font-weight="900" font-size="${v.mono}" fill="${pal.light}" style="font-family:${DISPLAY}">${esc(p.number)}</text>`
      + `<circle cx="${W - PAD - 14}" cy="${cy}" r="14" fill="${esc(dotColor)}"/>`;
  } else {
    const serial = p.serial ? cromoSerial(p.serial, p.printRun) : isNum(p.printRun) ? `×${p.printRun}` : "";
    const line = [[p.setCode, p.number].filter(Boolean).join(" "), serial].filter(Boolean).join(" · ");
    const label = v.label && p.rarityLabel ? S.fe(p.rarityLabel) : "";
    const O = S.me(line) * v.mono + v.tracking * [...line].length;
    const k = label ? S.pe(label, 800) * v.label + v.tracking * [...label].length : 0;
    const A = size === "sm" ? 5 : 3.4;
    const j = Math.min(1, 204 / (O + 12 + k + (label ? 6 : 0) + 2 * A));
    const M = HT - v.bar / 2 + v.mono * 0.36;
    const P = 222 - (label ? (k + 6) * j : 0) - A * j;
    const F = M - (label ? v.label * 0.36 : v.mono * 0.37) * j;
    if (line) body += `<text x="${PAD}" y="${n(M)}" font-weight="${size === "sm" ? 700 : 500}" font-size="${n(v.mono * j)}" letter-spacing="${n(v.tracking * j)}" fill="${pal.light}" style="font-family:${MONO}">${esc(line)}</text>`;
    body += `<circle cx="${n(P)}" cy="${n(F)}" r="${n(A * j)}" fill="${esc(dotColor)}"/>`;
    if (label) body += `<text x="222" y="${n(M)}" text-anchor="end" font-weight="800" font-size="${n(v.label * j)}" letter-spacing="${n(v.tracking * j)}" fill="${pal.accent}" textLength="${n(k * j - v.tracking * j)}" lengthAdjust="spacingAndGlyphs" style="font-family:${DISPLAY}">${esc(label)}</text>`;
  }
  return `<svg class="cromo__face" viewBox="0 0 ${W} ${HT}" aria-hidden="true"><defs>${defs}</defs>${body}</svg>`;
}

// ---- public API ----

const SIZES = new Set(["xs", "sm", "md", "lg"]);
const STATES = new Set(["owned", "missing", "locked", "hidden"]);
const LOCK_SVG = `<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="11" width="14" height="10" rx="2" fill="currentColor"/><path d="M8 11V8a4 4 0 0 1 8 0v3" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/></svg>`;

/**
 * Render one cromo as an HTML string.
 *
 * @param {object} card  catalog card {id, name, rarity, flavour, print_run, minted, hidden, ...}
 * @param {object} [opts]
 * @param {object}   [opts.set]       set object {id, name, color, released, cards} (colour, set name,
 *                                    and passing the same set.cards array keeps scenes unique per set)
 * @param {object[]} [opts.copies]    owned assets for this card ({serial, print_run, ...}); 0 = missing, >1 = dupes
 * @param {"xs"|"sm"|"md"|"lg"} [opts.size="md"]  64 / 120 / 176 / 280 px wide
 * @param {"owned"|"missing"|"locked"|"hidden"} [opts.state]  derived when omitted
 * @param {number}   [opts.value]     our private value, shown as a pill
 * @param {boolean}  [opts.showMeta]  caption under the card (name, rarity, serials, minted)
 * @param {boolean}  [opts.selected]  gold selection ring
 * @param {boolean}  [opts.fluid]     width 100% of the parent instead of the size's fixed width
 * @param {object}   [opts.rarities]  catalog.rarities, to use the server's labels and colours
 * @param {string}   [opts.symbol="P"] currency symbol for the value pill
 * @param {string}   [opts.className] extra classes on the root
 * @returns {string}
 */
export function cromo(card, opts = {}) {
  card = card || {};
  const set = opts.set || null;
  const copies = Array.isArray(opts.copies) ? opts.copies : [];
  const size = SIZES.has(opts.size) ? opts.size : "md";
  const rarity = RARITIES.includes(card.rarity) ? card.rarity : "common";
  const rinfo = (opts.rarities && opts.rarities[rarity]) || {};
  const rarColor = rinfo.color || RARITY_COLOR[rarity];
  const rarLabel = rinfo.label || RARITY_LABEL[rarity];
  const pid = parseId(card.id);
  const setCode = set?.id || pid.set;
  const setColor = /^#[0-9a-f]{3,8}$/i.test(set?.color || "") ? set.color : "#5C6B73";
  const number = String(pid.number).padStart(2, "0");
  const printRun = isNum(card.print_run) ? card.print_run : copies[0]?.print_run;

  let state = STATES.has(opts.state) ? opts.state : null;
  if (!state) {
    if (copies.length) state = "owned";
    else if (set && set.released === false) state = "locked";
    else if (card.hidden) state = "hidden";
    else state = "missing";
  }
  const name = state === "hidden" ? "???" : String(card.name ?? card.id ?? "");
  const serials = copies.map((c) => c?.serial).filter(isNum).sort((a, b) => a - b);
  const serial = serials[0];
  const flavour = size === "lg" && state === "owned" && card.flavour ? String(card.flavour) : "";
  const foil = state === "owned" && (rarity === "epic" || rarity === "legendary");

  const cls = ["cromo", `cromo--${rarity}`, `cromo--${size}`, `cromo--${state}`];
  if (copies.length > 1) cls.push("cromo--dup");
  if (foil) cls.push("cromo--foiled");
  if (opts.selected) cls.push("cromo--selected");
  if (opts.fluid) cls.push("cromo--fluid");
  if (opts.showMeta) cls.push("cromo--with-meta");
  if (opts.className) cls.push(String(opts.className));

  const stateWord = { owned: "", missing: ", not collected yet", locked: ", set not released yet", hidden: ", hidden card" }[state];
  const label = `${card.id ?? ""} ${state === "hidden" ? "hidden card" : name}${set?.name ? `, ${set.name}` : ""}, ${rarLabel}`
    + (serials.length ? `, ${serials.map((s) => cromoSerial(s, printRun)).join(" ")}` : "")
    + (copies.length > 1 ? `, ${copies.length} copies` : "") + stateWord;

  const style = `--set:${setColor};--rar:${rarColor};--cromo-bar:${(barFrac(size, !!flavour) * 100).toFixed(2)}%`;
  const seed = String(card.id ?? name);
  const scene = set?.cards && state !== "hidden" ? S.gt(set.cards, card.id) : undefined;

  let inner;
  if (state === "missing") {
    inner = art({ variant: "ghost", seed, name, setColor, scene })
      + `<div class="cromo__slot-no">${esc(number)}</div>`
      + (size === "xs" ? "" : `<div class="cromo__slot-name">${esc(name)}</div>`);
  } else {
    const silhouette = state !== "owned";
    inner = art({
      seed, name, title: state === "locked" ? "" : name, setColor, rarity, scene, size, silhouette,
      setCode, number: state === "hidden" && size !== "xs" ? "??" : number,
      serial, printRun, rarityLabel: rarLabel, rarityColor: rarColor, flavour: !!flavour,
    });
    if (flavour) inner += `<div class="cromo__flavour">${esc(flavour)}</div>`;
    if (state === "owned" && card.hidden && size !== "xs") inner += `<span class="cromo__secret">secreto</span>`;
  }

  let overlays = "";
  if (foil) overlays += `<div class="cromo__edge" aria-hidden="true"></div><div class="cromo__foil" aria-hidden="true"></div>`;
  if (state === "owned") overlays += `<div class="cromo__glare" aria-hidden="true"></div>`;
  if (state === "locked") overlays += `<div class="cromo__lock" aria-hidden="true">${LOCK_SVG}</div>`;
  if (state === "missing") overlays += `<span class="cromo__pip" aria-hidden="true"></span>`;
  if (state === "owned" && size === "xs" && copies.length <= 1) overlays += `<span class="cromo__own" aria-hidden="true"></span>`;
  if (copies.length > 1) overlays += `<span class="cromo__count" aria-hidden="true">×${copies.length}</span>`;
  if (isNum(opts.value) && size !== "xs") {
    overlays += `<span class="cromo__value" title="What this card is worth to us"><small>value</small>${esc(money(opts.value, opts.symbol || "P"))}</span>`;
  }

  let meta = "";
  if (opts.showMeta) {
    const bits = [esc(card.id ?? ""), `<b class="cromo__meta-rarity">${esc(rarLabel)}</b>`];
    if (serials.length) bits.push(esc(serials.map((s) => cromoSerial(s, printRun)).join(" ")));
    else if (isNum(card.minted) && isNum(printRun)) bits.push(`${esc(card.minted)}/${esc(printRun)} minted`);
    meta = `<div class="cromo__meta"><span class="cromo__meta-name">${esc(name)}</span><span class="cromo__meta-sub">${bits.join(" · ")}</span></div>`;
  }

  return `<div class="${esc(cls.join(" "))}" data-card="${esc(card.id ?? "")}" data-rarity="${rarity}" data-state="${state}"`
    + `${opts.selected ? ' data-selected="true"' : ""} style="${esc(style)}" role="img" aria-label="${esc(label)}">`
    + `<div class="cromo__frame"><div class="cromo__inner">${inner}</div>${overlays}</div>${meta}</div>`;
}

/**
 * Optional pointer tilt + glare (the official card follows the pointer).
 * Call once per container; returns a function that removes the listeners.
 * Does nothing when the user prefers reduced motion.
 */
export function cromoTilt(root = document) {
  if (typeof window === "undefined" || window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return () => {};
  const move = (e) => {
    const frame = e.target.closest?.(".cromo--owned:not(.cromo--xs) .cromo__frame");
    if (!frame) return;
    const r = frame.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width, y = (e.clientY - r.top) / r.height;
    frame.style.setProperty("--mx", `${(x * 100).toFixed(1)}%`);
    frame.style.setProperty("--my", `${(y * 100).toFixed(1)}%`);
    frame.style.setProperty("--ry", `${((x - 0.5) * 16).toFixed(2)}deg`);
    frame.style.setProperty("--rx", `${((0.5 - y) * 16).toFixed(2)}deg`);
  };
  const leave = (e) => {
    const frame = e.target.closest?.(".cromo__frame");
    if (frame) { frame.style.removeProperty("--rx"); frame.style.removeProperty("--ry"); }
  };
  root.addEventListener("pointermove", move);
  root.addEventListener("pointerout", leave);
  return () => { root.removeEventListener("pointermove", move); root.removeEventListener("pointerout", leave); };
}
